H.background();
const w = H.W;
const beta = Math.min(0.99, Math.max(0, P.beta));
const gamma = 1 / Math.sqrt(Math.max(1e-6, 1 - beta * beta));
const dtau = Math.max(0.1, P.dtau);
const dt = gamma * dtau;
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -1, yMax: 6 });
v.grid(); v.axes();
// Moving light-clock loops across the window; faster beta => faster horizontal drift.
const cx = (t * (0.6 + beta * 2.0)) % 11 - 0.5;
const baseY = 0.5, Lh = 3.0;
// Photon ticks at the PROPER rate inside the clock; the observer sees the clock
// run slow by gamma, so its bounce takes gamma*dtau of THEIR time.
const obsPeriod = Math.max(0.4, gamma * dtau);
const ph = (t % obsPeriod) / obsPeriod;
const photonY = baseY + (Lh / 2) * (1 - Math.cos(ph * H.TAU));
v.line(cx - 0.35, baseY, cx + 0.35, baseY, { color: H.colors.accent, width: 4 });
v.line(cx - 0.35, baseY + Lh, cx + 0.35, baseY + Lh, { color: H.colors.accent, width: 4 });
v.line(cx, baseY, cx, photonY, { color: H.colors.yellow, width: 1.5, dash: [3, 3] });
v.dot(cx, photonY, { r: 6, fill: H.colors.yellow });
v.arrow(cx, baseY + Lh + 0.7, cx + 0.4 + beta * 1.6, baseY + Lh + 0.7, { color: H.colors.warn, width: 2.5 });
H.text("Time dilation: Δt = γ·Δτ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("β = v/c = " + beta.toFixed(2) + "    γ = " + gamma.toFixed(3), 24, 52, { color: H.colors.sub, size: 13 });
H.text("Δτ moving clock = " + dtau.toFixed(2) + " s   →   Δt you measure = " + dt.toFixed(2) + " s", 24, 74, { color: H.colors.good, size: 13 });
H.legend([{ label: "light-clock photon", color: H.colors.yellow }, { label: "velocity v", color: H.colors.warn }], w - 200, 28);
